import{gt as e,it as t,n,rt as r}from"./chunks/framework.Dnkn0z2z.js";var i=JSON.parse(`{"title":"实现思路","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1791624692000}`),a={name:`guide/architecture.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="实现思路" tabindex="-1">实现思路 <a class="header-anchor" href="#实现思路" aria-label="Permalink to “实现思路”">​</a></h1><p>BubblesJS i18n 把国际化分成两条链路：开发时，CLI 从项目代码收集 key 并维护 JSON；运行时，core 加载 JSON、保存当前语言，React / Vue 适配层订阅变化并更新组件。JSON 是两条链路共同使用的词条格式。</p><h2 id="先看完整流程" tabindex="-1">先看完整流程 <a class="header-anchor" href="#先看完整流程" aria-label="Permalink to “先看完整流程”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>开发与翻译维护</span></span>
<span class="line"><span></span></span>
<span class="line"><span>项目源码中的 tr(&quot;welcome&quot;, { name })</span></span>
<span class="line"><span>               │</span></span>
<span class="line"><span>               │ CLI：扫描静态 key，比较并同步</span></span>
<span class="line"><span>               ▼</span></span>
<span class="line"><span>    zh-CN.json / en-US.json</span></span>
<span class="line"><span>               ⇅</span></span>
<span class="line"><span>        Excel 翻译表</span></span>
<span class="line"><span></span></span>
<span class="line"><span>应用运行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>默认中文 JSON ── message ──────► core store</span></span>
<span class="line"><span>                                  ▲</span></span>
<span class="line"><span>其他语言 JSON ── loaderMessage ───┘</span></span>
<span class="line"><span>                                  │</span></span>
<span class="line"><span>                           locale + message</span></span>
<span class="line"><span>                                  │ 状态订阅</span></span>
<span class="line"><span>                       ┌──────────┴──────────┐</span></span>
<span class="line"><span>                       ▼                     ▼</span></span>
<span class="line"><span>                  React Hooks          Vue Composables</span></span>
<span class="line"><span>                       │                     │</span></span>
<span class="line"><span>                       └───── tr(key) ───────┘</span></span>
<span class="line"><span>                                  ▼</span></span>
<span class="line"><span>                             组件中的文本</span></span></code></pre></div><p>本仓库已实现「项目扫描 → JSON」、JSON ⇄ Excel 双向转换和运行时翻译。Excel 交给译者维护，<code>excel export</code> 负责导出，<code>excel import</code> 负责将译文写回各语言 JSON，应用继续读取 JSON。</p><table tabindex="0"><thead><tr><th>层</th><th>包</th><th>负责的事情</th></tr></thead><tbody><tr><td>词条维护</td><td><code>@bubblesjs/i18n-cli</code></td><td>扫描项目、维护 JSON、转换 Excel 翻译表</td></tr><tr><td>翻译运行时</td><td><code>@bubblesjs/i18n-core</code></td><td>保存语言与词条、插值、异步切换、通知订阅者</td></tr><tr><td>React 接入</td><td><code>@bubblesjs/i18n-react</code></td><td>Context Provider 与外部状态订阅 Hooks</td></tr><tr><td>Vue 接入</td><td><code>@bubblesjs/i18n-vue</code></td><td>provide / inject 与响应式 Composables</td></tr></tbody></table><p>CLI 独立于运行时，也不依赖 React 或 Vue。应用可以只安装 core 与所用框架的适配器，开发环境再按需安装 CLI。</p><h2 id="词条为何使用扁平-json" tabindex="-1">词条为何使用扁平 JSON <a class="header-anchor" href="#词条为何使用扁平-json" aria-label="Permalink to “词条为何使用扁平 JSON”">​</a></h2><p>源码使用稳定的 key，JSON 保存每种语言对应的文本：</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;welcome&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bubbles&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;menu.home&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-84" id="tab-85" checked><label data-title="zh-CN.json" for="tab-85">zh-CN.json</label><input type="radio" name="group-84" id="tab-86"><label data-title="en-US.json" for="tab-86">en-US.json</label></div><div class="blocks"><div class="language-json active"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;welcome&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你好，{name}！&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;menu.home&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;首页&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;welcome&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello, {name}!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;menu.home&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Home&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></div></div><p>词条类型为 <code>Record&lt;string, string&gt;</code>。<code>menu.home</code> 是一个完整字符串键，不会展开成嵌套路径。这样扫描、同步、运行时查找和 Excel 的 key 列都使用同一种标识。</p><p>key 也可以直接使用中文，如 <code>tr(&quot;保存&quot;)</code>。无论选择语义 key 还是中文 key，都应在项目中保持一致，译文填写在对应语言的 JSON 中。</p><h2 id="cli-如何把项目扫描成-json" tabindex="-1">CLI 如何把项目扫描成 JSON <a class="header-anchor" href="#cli-如何把项目扫描成-json" aria-label="Permalink to “CLI 如何把项目扫描成 JSON”">​</a></h2><ol><li>读取 <code>i18n.config.*</code>，按 <code>projects</code> 确定源码范围和各语言的 JSON 路径。</li><li>用 glob 枚举源码文件，排除依赖、构建产物和配置中忽略的文件，跳过二进制文件。</li><li>根据 <code>callNames</code> 匹配翻译调用，解析第一个静态字符串参数，记录 key、文件、行和列。</li><li>每个项目合并并去重 key 集合，与各语言 JSON 的现有 key 比较。</li><li><code>sync</code> 补入缺失 key，保留已有译文；<code>check</code> 只计算差异，用退出码供 CI 判断。</li></ol><p>例如源码新增 <code>tr(&quot;menu.about&quot;)</code> 后执行 <code>sync</code>，各语言 JSON 都会补入：</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;menu.about&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;menu.about&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>新增值先使用 key 本身，不会自动生成译文。之后把中文改为「关于」、英文改为「About」。已有的 <code>welcome</code> 和 <code>menu.home</code> 译文保持原值。</p><p>扫描包含在 <code>sync</code> / <code>check</code> 中，没有独立的 <code>scan</code> 命令。可以用 <code>sync --dry-run</code> 预览差异，默认不会删除未使用词条；只有显式使用 <code>--clean</code> 才清理。</p><p>扫描器是文本扫描，不解析完整的 JavaScript / Vue AST，也不执行源码。<code>tr(variable)</code>、拼接表达式和带插值的模板字符串无法提取；注释或其他字符串中形似调用的文本也可能被识别。使用动态 key 或清理词条前，应检查扫描报告。</p><p>同步会先校验一个项目的所有语言包，计算增删计划，再写入文件。写入通过临时文件替换完成，原子性以单个 JSON 文件为单位。具体命令、配置和报告见<a href="./cli">CLI 使用</a>。</p><h2 id="core-如何翻译和切换语言" tabindex="-1">core 如何翻译和切换语言 <a class="header-anchor" href="#core-如何翻译和切换语言" aria-label="Permalink to “core 如何翻译和切换语言”">​</a></h2><p>core 的中心是一个自建的可订阅状态容器，暴露 <code>getState()</code>、<code>setState()</code> 和 <code>subscribe()</code>。国际化状态包含四项：</p><table tabindex="0"><thead><tr><th>状态</th><th>作用</th></tr></thead><tbody><tr><td><code>locale</code></td><td>当前语言，如 <code>zh-CN</code></td></tr><tr><td><code>message</code></td><td>当前语言的扁平词条</td></tr><tr><td><code>tr(key, values?)</code></td><td>查找文本并替换 <code>{name}</code> 等占位符</td></tr><tr><td><code>loadLocale(locale)</code></td><td>异步加载并切换语言</td></tr></tbody></table><p><code>tr</code> 每次从容器读取最新的 <code>message</code>，查找 key 后交给 <code>formatMessage</code> 插值。缺失 key 返回 key 本身，缺失插值参数保留原占位符；空字符串译文会保留。</p><p>应用提供 <code>loaderMessage(locale)</code> 来加载对应语言包。默认示例直接使用 <code>import(\`./locales/\${nextLocale}.json\`)</code>，路径由应用提供，构建器负责 JSON 分包。core 不规定资源路径或请求方法，也可以通过加载器请求应用自己的接口。默认按需加载流程为：</p><ol><li>静态导入默认中文 JSON，再调用 <code>createI18n({ locale: &quot;zh-CN&quot;, message: zhCN, loaderMessage })</code> 同步创建容器；初始化不调用加载器。</li><li>把返回的容器交给 React / Vue 的 Provider，再挂载应用；其他语言包此时尚未加载。</li><li>用户切换时调用 <code>loadLocale(&quot;en-US&quot;)</code>，才通过同一个 <code>loaderMessage</code> 动态加载英文 JSON。</li></ol><p>创建容器有两种方式：</p><table tabindex="0"><thead><tr><th>入口</th><th>适用场景</th><th>首屏词条来自哪里</th></tr></thead><tbody><tr><td><code>createI18n({ locale, message, loaderMessage })</code></td><td>已有首屏词条，直接同步创建</td><td>传入的 <code>message</code></td></tr><tr><td><code>await initI18n({ locale, loaderMessage })</code></td><td>先按语言异步加载，再启动应用</td><td>等待 <code>loaderMessage</code> 的结果</td></tr></tbody></table><p>接入教程默认使用 <code>createI18n</code>：通过 <code>message</code> 提供静态导入的首屏词条，切换时再调用加载器。需要异步获取首屏词条时，使用 <code>initI18n</code>。只有 <code>initI18n</code> 会在初始化时读取保存的语言偏好，再回退到默认语言；<code>createI18n</code> 直接使用传入的 <code>locale</code> 与 <code>message</code>。</p><p>切换时，<code>loadLocale</code> 先调用应用提供的 <code>loaderMessage</code>。加载期间保留原语言和词条，完成后一起提交 <code>locale</code> 与 <code>message</code>，再通知组件。每次请求都有递增编号，较早请求的结果不会覆盖较晚的语言选择。</p><p>如果加载器抛出异常，core 会记录警告，并把目标语言与空词条提交到容器，翻译回退到 key。需要缓存或地区回退时，应在加载器中明确实现相应策略。持久化只保存语言偏好，JSON 词条仍由加载器提供。</p><p>完整 API 和边界行为见<a href="./core">核心容器</a>。</p><h2 id="react-与-vue-如何更新组件" tabindex="-1">React 与 Vue 如何更新组件 <a class="header-anchor" href="#react-与-vue-如何更新组件" aria-label="Permalink to “React 与 Vue 如何更新组件”">​</a></h2><p>两个适配器都接收同一种 core store，不重复实现翻译规则：</p><table tabindex="0"><thead><tr><th>过程</th><th>React</th><th>Vue</th></tr></thead><tbody><tr><td>向组件树提供容器</td><td><code>I18nProvider</code> / Context</td><td><code>I18nProvider</code> / provide</td></tr><tr><td>在子组件取得容器</td><td>Context</td><td>inject</td></tr><tr><td>订阅状态变化</td><td><code>useSyncExternalStore</code></td><td><code>shallowRef</code> 保存状态快照</td></tr><tr><td>暴露组件可用值</td><td><code>useI18n()</code> 返回翻译方法、切换方法和当前语言</td><td><code>useI18n()</code> 返回翻译方法、切换方法和 computed 语言引用</td></tr><tr><td>清理订阅</td><td>React 订阅生命周期</td><td><code>onScopeDispose</code></td></tr></tbody></table><p>所以切换语言的实际路径是：<strong>组件调用 <code>loadLocale</code> → core 更新状态 → 适配器收到通知 → 组件重新渲染译文</strong>。无需刷新页面。</p><p>两个框架都使用 <code>const { tr, locale, loadLocale } = useI18n()</code>。<code>tr</code> 和 <code>loadLocale</code> 都是普通函数；React 的 <code>locale</code> 是当前语言值，Vue 的 <code>locale</code> 是 computed 引用，在脚本中读取 <code>locale.value</code>，模板中自动解包。Vue 的 <code>tr</code> 包装函数会读取响应式状态快照，在模板或 computed 中调用时建立依赖。服务端渲染时，应为每个请求创建独立容器，并让客户端水合使用相同的初始语言和词条。</p><p>可直接照着接入的完整文件示例见<a href="./react">React 接入与使用</a>和<a href="./vue">Vue 接入与使用</a>。</p><p>同一页面的全局区域和项目区域可以分别初始化独立容器，各自持有 <code>locale</code>、<code>message</code> 和加载器。外层 Provider 提供全局容器，内层 Provider 提供项目容器；后代组件的 <code>useI18n()</code> 读取最近的 Provider，局部切换只更新项目容器，全局切换只更新全局容器。读取局部词条的业务组件应放在局部 Provider 的后代中。</p><p>两个容器的词条不会自动合并，局部缺失的 key 仍回退到 key 本身。整体接入方式见<a href="./scopes">全局与局部使用</a>，可复制的框架示例见 <a href="./react#局部使用-独立项目语言">React 局部使用</a>和 <a href="./vue#局部使用-独立项目语言">Vue 局部使用</a>。</p><h2 id="json-⇄-excel-如何协作" tabindex="-1">JSON ⇄ Excel 如何协作 <a class="header-anchor" href="#json-⇄-excel-如何协作" aria-label="Permalink to “JSON ⇄ Excel 如何协作”">​</a></h2><p>每个项目通过 <code>excel.file</code> 配置一个 <code>.xlsx</code> 文件，默认工作表为 <code>translations</code>，可用 <code>excel.sheet</code> 指定。行是 key，列是语言：</p><table tabindex="0"><thead><tr><th>key</th><th>中文</th><th>English</th><th>备注</th></tr></thead><tbody><tr><td>welcome</td><td>你好，{name}！</td><td>Hello, {name}!</td><td>首屏欢迎语</td></tr><tr><td>menu.home</td><td>首页</td><td>Home</td><td>导航</td></tr></tbody></table><p>协作流程为：扫描项目补齐 JSON → <code>excel export</code> 导出 Excel → 译者填写语言列 → <code>excel import</code> 导入 JSON → 应用加载新词条。两个方向都会检测已有值冲突，使用 <code>-f</code> 才覆盖；目标端多出的 key 默认保留，使用 <code>--prune</code> 才清理。</p><p>Excel 只参与开发时的词条维护，不进入浏览器运行时。具体命令、表结构和冲突规则见 <a href="./cli#excel-workflow">CLI 使用</a>；npm 包的功能发布状态请查看 <a href="https://github.com/bubblesplant/i18n/releases" target="_blank" rel="noreferrer">GitHub Releases</a>。</p><h2 id="对照源码阅读" tabindex="-1">对照源码阅读 <a class="header-anchor" href="#对照源码阅读" aria-label="Permalink to “对照源码阅读”">​</a></h2><table tabindex="0"><thead><tr><th>实现</th><th>源码入口</th></tr></thead><tbody><tr><td>状态、翻译与语言加载</td><td><a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-core/src/i18n.ts" target="_blank" rel="noreferrer">core / i18n.ts</a>、<a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-core/src/store.ts" target="_blank" rel="noreferrer">store.ts</a></td></tr><tr><td>React 订阅</td><td><a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-react/src/index.tsx" target="_blank" rel="noreferrer">react / index.tsx</a>、<a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-react/src/use-store.ts" target="_blank" rel="noreferrer">use-store.ts</a></td></tr><tr><td>Vue 响应式订阅</td><td><a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-vue/src/index.ts" target="_blank" rel="noreferrer">vue / index.ts</a>、<a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-vue/src/use-store.ts" target="_blank" rel="noreferrer">use-store.ts</a></td></tr><tr><td>扫描与 JSON 同步</td><td><a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-cli/src/scanner.ts" target="_blank" rel="noreferrer">cli / scanner.ts</a>、<a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-cli/src/sync.ts" target="_blank" rel="noreferrer">sync.ts</a></td></tr></tbody></table>`,48)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};